private string strFTPFolder = @"HRS_Task_Files"; // thư mục FTP chứa file đính kèm quyết định công tác

private void FTPUploadFile()
{
    string strLocalPath = txtFilePath.Text;
    if (strLocalPath != "")
    {
        Libs.FTPLib objFTP = new FTPLib();
        if (!objFTP.UploadLargeFile(strLocalPath, this.strFTPFolder, itemTaskEditing.Link))
            ErrorManager.Error(objFTP.ErrorException.Message);
    }
}

private void FTPDeleteFile()
{
    string strFtpPath = System.IO.Path.Combine(this.strFTPFolder, itemTaskEditing.Link);
    if (itemTaskEditing.Link != "")
    {
        Libs.FTPLib objFTP = new FTPLib();
        if (!objFTP.Delete(strFtpPath))
            ErrorManager.Error(objFTP.ErrorException.Message);
    }

    itemTaskEditing.Link = "";
    lbtDeleteFile.Visible = false;
    lbtViewFile.Visible = false;
}

private void FTPDownloadFile()
{
    string strFtpPath = System.IO.Path.Combine(this.strFTPFolder, itemTaskEditing.Link);
    string strLocalDir = System.IO.Path.Combine(Application.StartupPath, @"FTPFile", strFTPFolder);
    if (itemTaskEditing.Link != "")
    {
        FTPLib objFTP = new FTPLib();
        string strLocalPath = objFTP.Download(strFtpPath, strLocalDir);
        if (!string.IsNullOrEmpty(strLocalPath))
        {
            System.Diagnostics.Process.Start(strLocalPath);
        }
        else
        {
            ErrorManager.Error(objFTP.ErrorException.Message);
        }
    }
}

private string GetAttachmentFileName(long? lngFileTaskID, string strLocalPath)
{
    string strExt = System.IO.Path.GetExtension(strLocalPath);
    if (strExt == null)
        strExt = "";
    return String.Format("{0}{1}", lngFileTaskID, strExt);
}

