private void btnBrowse_Click(object sender, EventArgs e)
{
    try
    {
        OpenFileDialog dlgOpen = new OpenFileDialog();
        dlgOpen.Filter = "*.pdf|*.pdf|*.doc|*.docx|*.docx|*.jpg|*.jpg|*.png|*.png|*.*|*.*";
        if (dlgOpen.ShowDialog() == DialogResult.OK)
        {
            if (dlgOpen.FileName != "")
            {
                txtFilePath.Text = dlgOpen.FileName;
            }
        }
    }
    catch (Exception objExc)
    {
        Libs.ErrorManager.Error("Lấy dữ liệu file bị lỗi!: " + objExc.ToString());
    }
}

private void lbtDeleteFile_LinkClicked(object sender, LinkLabelLinkClickedEventArgs e)
{
    if (MessageManager.Confirm("Bạn có chắc chắn muốn xóa tập tin '" + itemTaskEditing.Link + "' trên máy chủ?") == System.Windows.Forms.DialogResult.Yes)
    {
        FTPDeleteFile();

        if (IsValidEditForm())
            SaveData();
    }
}

private void lbtViewFile_LinkClicked(object sender, LinkLabelLinkClickedEventArgs e)
{
    FTPDownloadFile();
}

