private void SyncItemTaskLinkFromDb()
{
    if (lngTaskID == null || lngTaskID < 1)
        return;
    if (!string.IsNullOrEmpty(itemTaskEditing.Link))
        return;

    HRS_Task objReload = new HRS_Task();
    objReload.TaskID = lngTaskID;
    if (objReload.Get() && !string.IsNullOrEmpty(objReload.Link))
        itemTaskEditing.Link = objReload.Link;
}

private string GetTaskAttachmentLink()
{
    SyncItemTaskLinkFromDb();
    if (itemTaskEditing.Link == null)
        return "";
    return itemTaskEditing.Link.Trim();
}

private void RefreshAttachmentLinkUI()
{
    string strLink = GetTaskAttachmentLink();
    lbtViewFile.Visible = strLink != "";
    lbtDeleteFile.Visible = strLink != "" && btnSave.Enabled;
}

private bool FTPUploadFile(string strRemoteFileName)
{
    string strLocalPath = txtFilePath.Text;
    if (strLocalPath == "")
        return true;

    if (string.IsNullOrEmpty(strRemoteFileName))
    {
        ErrorManager.Error("Không xác định được tên file để upload lên FTP!");
        return false;
    }

    if (!System.IO.File.Exists(strLocalPath))
    {
        ErrorManager.Error("Không tìm thấy file trên máy: " + strLocalPath);
        return false;
    }

    Libs.FTPLib objFTP = new FTPLib();
    if (!objFTP.UploadLargeFile(strLocalPath, this.strFTPFolder, strRemoteFileName))
    {
        if (objFTP.ErrorException != null)
            ErrorManager.Error(objFTP.ErrorException.Message);
        else
            ErrorManager.Error("Upload file lên FTP thất bại. Kiểm tra cấu hình FTP và thư mục " + this.strFTPFolder + " trên máy chủ.");
        return false;
    }
    return true;
}

private void FTPDeleteFile()
{
    string strLink = GetTaskAttachmentLink();
    if (strLink != "")
    {
        string strFtpPath = System.IO.Path.Combine(this.strFTPFolder, strLink);
        Libs.FTPLib objFTP = new FTPLib();
        if (!objFTP.Delete(strFtpPath))
        {
            if (objFTP.ErrorException != null)
                ErrorManager.Error(objFTP.ErrorException.Message);
            else
                ErrorManager.Error("Xóa file trên FTP thất bại.");
            return;
        }
    }

    itemTaskEditing.Link = "";
    RefreshAttachmentLinkUI();
}

private void FTPDownloadFile()
{
    string strLink = GetTaskAttachmentLink();
    if (strLink == "")
    {
        ErrorManager.Warning("Không có tên file đính kèm. Kiểm tra cột Link và store HRS_Task_GET trên database.");
        return;
    }

    string strFtpPath = System.IO.Path.Combine(this.strFTPFolder, strLink);
    string strLocalDir = System.IO.Path.Combine(Application.StartupPath, @"FTPFile", this.strFTPFolder);
    FTPLib objFTP = new FTPLib();
    string strLocalPath = objFTP.Download(strFtpPath, strLocalDir);
    if (!string.IsNullOrEmpty(strLocalPath))
    {
        System.Diagnostics.Process.Start(strLocalPath);
    }
    else
    {
        if (objFTP.ErrorException != null)
            ErrorManager.Error(objFTP.ErrorException.Message);
        else
            ErrorManager.Error("Không tải được file từ FTP. Kiểm tra file '" + strLink + "' trong thư mục " + this.strFTPFolder + ".");
    }
}

