/*
	Deploy: cột Link + store ADD/EDIT/GET — HRS_Training (tab Đào tạo)
	Date  : 2025-09-22
*/

If Not Exists (
	Select 1
	From sys.columns
	Where object_id = Object_Id(N'dbo.HRS_Training')
		And name = N'Link'
)
Begin
	Alter Table [dbo].[HRS_Training]
	Add [Link] nvarchar(500) Null
End
Go

If Object_Id(N'dbo.HRS_Training_ADD', N'P') Is Null
	Exec(N'Create Procedure [dbo].[HRS_Training_ADD] As Begin Set Nocount On; End');
Go

Alter Procedure [dbo].[HRS_Training_ADD]
(
	@EmployeeID bigint = null,
	@TrainingFrom date = null,
	@TrainingTo date = null,
	@TrainingFromYear int = null,
	@TrainingToYear int = null,
	@TrainingLevelID int = 0,
	@TrainingFormID int = 0,
	@TrainingSchool nvarchar(150) = null,
	@TrainingCountryID nvarchar(20) = 0,
	@FeeTypeID int = 0,
	@Fee int = null,
	@TrainingContent nvarchar(300) = null,
	@TrainingLen nvarchar(50) = null,
	@DecidedNo nvarchar(50) = null,
	@DecidedDate date = null,
	@DecidedUser bigint = 0,
	@IsSigned bit = 0,
	@Description nvarchar(200) = null,
	@CreatedUser nvarchar(20) = N'administrator',
	@IsTraining bit = 0,
	@CerNo nvarchar(50) = null,
	@CerDate date = null,
	@CerPlace nvarchar(100) = null,
	@SpecialJobID int = 0,
	@Link nvarchar(500) = null
)
As
Begin
	Set Nocount Off

	Insert Into [HRS_Training]
	(
		[EmployeeID],
		[TrainingFrom],
		[TrainingTo],
		[TrainingFromYear],
		[TrainingToYear],
		[TrainingLevelID],
		[TrainingFormID],
		[TrainingSchool],
		[TrainingCountryID],
		[FeeTypeID],
		[Fee],
		[TrainingContent],
		[TrainingLen],
		[DecidedNo],
		[DecidedDate],
		[DecidedUser],
		[IsSigned],
		[Description],
		[CreatedUser],
		[IsTraining],
		[CerNo],
		[CerDate],
		[CerPlace],
		[SpecialJobID],
		[Link]
	)
	Values
	(
		@EmployeeID,
		@TrainingFrom,
		@TrainingTo,
		@TrainingFromYear,
		@TrainingToYear,
		@TrainingLevelID,
		@TrainingFormID,
		@TrainingSchool,
		@TrainingCountryID,
		@FeeTypeID,
		@Fee,
		@TrainingContent,
		@TrainingLen,
		@DecidedNo,
		@DecidedDate,
		@DecidedUser,
		@IsSigned,
		@Description,
		@CreatedUser,
		@IsTraining,
		@CerNo,
		@CerDate,
		@CerPlace,
		@SpecialJobID,
		@Link
	)

	Select Scope_Identity()
End
Go

If Object_Id(N'dbo.HRS_Training_EDIT', N'P') Is Null
	Exec(N'Create Procedure [dbo].[HRS_Training_EDIT] As Begin Set Nocount On; End');
Go

Alter Procedure [dbo].[HRS_Training_EDIT]
(
	@TrainingID bigint,
	@EmployeeID bigint = null,
	@TrainingFrom date = null,
	@TrainingTo date = null,
	@TrainingFromYear int = null,
	@TrainingToYear int = null,
	@TrainingLevelID int = 0,
	@TrainingFormID int = 0,
	@TrainingSchool nvarchar(150) = null,
	@TrainingCountryID nvarchar(20) = 0,
	@FeeTypeID int = 0,
	@Fee int = null,
