/*
	Deploy: cột Link + store ADD/EDIT/GET — HRS_Contract (tab Quá trình lương)
	Date  : 2025-09-22
*/

If Not Exists (
	Select 1
	From sys.columns
	Where object_id = Object_Id(N'dbo.HRS_Contract')
		And name = N'Link'
)
Begin
	Alter Table [dbo].[HRS_Contract]
	Add [Link] nvarchar(500) Null
End
Go

If Object_Id(N'dbo.HRS_Contract_ADD', N'P') Is Null
	Exec(N'Create Procedure [dbo].[HRS_Contract_ADD] As Begin Set Nocount On; End');
Go

Alter Procedure [dbo].[HRS_Contract_ADD]
(
	@EmployeeID bigint = null,
	@ContractNo nvarchar(50) = null,
	@ContractTypeID int = 0,
	@ContractDate date = null,
	@ExpiredDate date = null,
	@SalaryQuotaID int = 0,
	@SalaryLevel int = 1,
	@SalaryRatio decimal(8, 3) = 1,
	@OverFrameSub decimal(8, 3) = 1,
	@Salary decimal(18, 3) = 0,
	@SalarySpecial decimal(18, 3) = 0,
	@IsActived bit = 1,
	@IsSigned bit = 0,
	@BeforeContractID bigint = 0,
	@Description nvarchar(1000) = null,
	@CreatedUser nvarchar(20) = N'admin',
	@ApplyDate date = null,
	@NextApplyDate date = null,
	@NextSalaryQuotaID int = null,
	@NextSalaryLevel int = null,
	@NextSalaryRatio decimal(8, 3) = null,
	@NextOverFrameSub decimal(8, 3) = null,
	@Link nvarchar(500) = null
)
As
Begin
	Set Nocount Off

	Insert Into [HRS_Contract]
	(
		[EmployeeID],
		[ContractNo],
		[ContractTypeID],
		[ContractDate],
		[ExpiredDate],
		[SalaryQuotaID],
		[SalaryLevel],
		[SalaryRatio],
		[OverFrameSub],
		[Salary],
		[SalarySpecial],
		[IsActived],
		[IsSigned],
		[BeforeContractID],
		[Description],
		[CreatedUser],
		[ApplyDate],
		[NextApplyDate],
		[NextSalaryQuotaID],
		[NextSalaryLevel],
		[NextSalaryRatio],
		[NextOverFrameSub],
		[Link]
	)
	Values
	(
		@EmployeeID,
		@ContractNo,
		@ContractTypeID,
		@ContractDate,
		@ExpiredDate,
		@SalaryQuotaID,
		@SalaryLevel,
		@SalaryRatio,
		@OverFrameSub,
		@Salary,
		@SalarySpecial,
		@IsActived,
		@IsSigned,
		@BeforeContractID,
		@Description,
		@CreatedUser,
		@ApplyDate,
		@NextApplyDate,
		@NextSalaryQuotaID,
		@NextSalaryLevel,
		@NextSalaryRatio,
		@NextOverFrameSub,
		@Link
	)

	Select Scope_Identity()
End
Go

If Object_Id(N'dbo.HRS_Contract_EDIT', N'P') Is Null
	Exec(N'Create Procedure [dbo].[HRS_Contract_EDIT] As Begin Set Nocount On; End');
Go

Alter Procedure [dbo].[HRS_Contract_EDIT]
(
	@ContractID bigint,
	@EmployeeID bigint = null,
	@ContractNo nvarchar(50) = null,
	@ContractTypeID int = 0,
	@ContractDate date = null,
	@ExpiredDate date = null,
	@SalaryQuotaID int = 0,
	@SalaryLevel int = 1,
	@SalaryRatio decimal(8, 3) = 1,
	@OverFrameSub decimal(8, 3) = 1,
	@Salary decimal(18, 3) = 0,
	@SalarySpecial decimal(18, 3) = 0,
	@IsActived bit = 1,
	@IsSigned bit = 0,
	@BeforeContractID bigint = 0,
	@Description nvarchar(1000) = null,
	@UpdatedUser nvarchar(20) = null,
	@ApplyDate date = null,
	@NextApplyDate date = null,
	@NextSalaryQuotaID int = null,
	@NextSalaryLevel int = null,
	@NextSalaryRatio decimal(8, 3) = null,
	@NextOverFrameSub decimal(8, 3) = null,
	@Link nvarchar(500) = null
)
As
Begin
	Set Nocount Off

	Update [HRS_Contract]
	Set
		[EmployeeID] = @EmployeeID,
		[ContractNo] = @ContractNo,
		[ContractTypeID] = @ContractTypeID,
		[ContractDate] = @ContractDate,
		[ExpiredDate] = @ExpiredDate,
		[SalaryQuotaID] = @SalaryQuotaID,
		[SalaryLevel] = @SalaryLevel,
		[SalaryRatio] = @SalaryRatio,
		[OverFrameSub] = @OverFrameSub,
		[Salary] = @Salary,
		[SalarySpecial] = @SalarySpecial,
		[IsActived] = @IsActived,
		[IsSigned] = @IsSigned,
		[BeforeContractID] = @BeforeContractID,
		[Description] = @Description,
		[UpdatedDate] = GetDate(),
		[UpdatedUser] = @UpdatedUser,
		[ApplyDate] = @ApplyDate,
		[NextApplyDate] = @NextApplyDate,
		[NextSalaryQuotaID] = @NextSalaryQuotaID,
		[NextSalaryLevel] = @NextSalaryLevel,
		[NextSalaryRatio] = @NextSalaryRatio,
		[NextOverFrameSub] = @NextOverFrameSub,
		[Link] = @Link
	Where
		[ContractID] = @ContractID
End
Go

If Object_Id(N'dbo.HRS_Contract_GET', N'P') Is Null
	Exec(N'Create Procedure [dbo].[HRS_Contract_GET] As Begin Set Nocount On; End');
Go

Alter Procedure [dbo].[HRS_Contract_GET]
(
	@ContractID bigint
)
As
Begin
	Set Nocount On

	Select
		[ContractID],
		[EmployeeID],
		[ContractNo],
		[ContractTypeID],
		[ContractDate],
		[ExpiredDate],
		[SalaryQuotaID],
		[SalaryLevel],
		[SalaryRatio],
		[OverFrameSub],
		[Salary],
		[SalarySpecial],
		[IsActived],
		[IsSigned],
		[BeforeContractID],
		[Description],
		[CreatedDate],
		[CreatedUser],
		[UpdatedDate],
		[UpdatedUser],
		[IsDeleted],
		[DeletedDate],
		[DeletedUser],
		[ApplyDate],
		[NextApplyDate],
		[NextSalaryQuotaID],
		[NextSalaryLevel],
		[NextSalaryRatio],
		[NextOverFrameSub],
		[Link]
	From [HRS_Contract]
	Where
		([ContractID] = @ContractID)
		And ([IsDeleted] = 0)
End
Go
